44	import streamDeck, { SingletonAction, type KeyAction, type WillAppearEvent, type WillDisappearEvent } from "@elgato/streamdeck";
45	import { faceImage } from "../face.ts";
46	import type { DeckState, Face } from "../state.ts";
47	import { store, wire, ensureConnected } from "../plugin.ts";
48	
49	/**
50	 * Whether the plugin should be holding its socket.
51	 *
52	 * Configuration, not visibility. `willAppear` fires only for the visible
53	 * page of the active profile, and a streamer whose keys live in the
54	 * Runlog profile would otherwise have no socket while that profile was
55	 * in the background — so the plugin could never learn a run had started,
56	 * and could never switch to the profile. Visible keys decide what is
57	 * drawn; this decides whether anyone is listening.
58	 */
59	export function shouldConnect(x: { session: boolean; configured: boolean; visible: number }): boolean {
60	  return x.session && x.configured;
61	}
62	
63	export abstract class RunlogAction<S extends object = object> extends SingletonAction<S> {
64	  private unsubscribe: (() => void) | null = null;
65	
66	  abstract face(state: DeckState, settings: S, now: number): Face;
67	
68	  override async onWillAppear(ev: WillAppearEvent<S>): Promise<void> {
69	    await streamDeck.settings.setGlobalSettings({ ...(await streamDeck.settings.getGlobalSettings()), configured: true });
70	    ensureConnected();
71	    this.unsubscribe ??= store.subscribe(() => this.redrawAll());
72	    await this.draw(ev.action as KeyAction<S>, ev.payload.settings);
73	  }
74	
75	  override onWillDisappear(_ev: WillDisappearEvent<S>): void {
76	    if ([...this.actions].length === 0) {
77	      this.unsubscribe?.();
78	      this.unsubscribe = null;
79	    }
80	  }
81	
82	  protected async draw(action: KeyAction<S>, settings: S): Promise<void> {
83	    const face = this.face(store.state, settings, Date.now());
84	    if (action.isKey()) {
85	      await action.setImage(faceImage(face));
86	      await action.setTitle("");
87	    }
88	    if (action.isDial()) await action.setFeedback({ title: face.when ?? "", value: face.title });
89	  }
90	
91	  private redrawAll(): void {
92	    for (const a of this.actions) void a.getSettings().then((s) => this.draw(a as KeyAction<S>, s));
93	  }
94	
95	  /** A press, with the flash the server's answer will turn into. */
96	  protected async send(action: KeyAction<S>, p: Parameters<typeof wire.press>[0]): Promise<void> {
97	    const ref = wire.press(p);
98	    if (!ref) {
99	      await action.showAlert();
100	      return;
101	    }
102	    const off = store.subscribe((s) => {
103	      if (s.flash?.ref !== ref) return;
104	      off();
105	      void (s.flash.ok ? action.showOk() : action.showAlert());
106	    });
107	  }
108	}
