1	import streamDeck from "@elgato/streamdeck";
2	
3	import { Connect } from "./actions/connect.ts";
4	import { Metric } from "./actions/metric.ts";
5	import { Next } from "./actions/next.ts";
6	import { Press } from "./actions/press.ts";
7	import { Run } from "./actions/run.ts";
8	import { Undo } from "./actions/undo.ts";
9	import { loadSession, normalizeBase, signIn, signOut, type Account } from "./session.ts";
10	import { openWire } from "./socket.ts";
11	import { makeStore } from "./store.ts";
12	import { idleDeadline } from "./state.ts";
13	
14	/** Where Runlog lives when the streamer has not said otherwise. */
15	const DEFAULT_API = "https://runlog.scrthq.com";
16	
17	/**
18	 * What the plugin keeps between launches.
19	 *
20	 * The address and the pinned run, and nothing else: global settings are
21	 * handed to the property inspector, which is a web view, so the session
22	 * never comes near them. It lives in a file of the plugin's own.
23	 */
24	type Globals = { apiBase?: string; pinned?: string | null };
25	
26	let apiBase = DEFAULT_API;
27	
28	export const store = makeStore();
29	export const wire = openWire((): Account => ({ apiBase }), store);
30	
31	/**
32	 * Switching the deck on.
33	 *
34	 * The address is read again first, so the one the streamer last typed is the
35	 * one dialed. Reconnecting through drops after that is the wire's own job.
36	 */
37	export function turnOn(): void {
38	  if (store.state.on) return;
39	  store.dispatch({ t: "on", on: true });
40	  void (async () => {
41	    await readGlobals();
42	    streamDeck.logger.info("on: connecting");
43	    wire.connect();
44	  })();
45	}
46	
47	/** Switching it off, by a press or - with `idle` - by the deck's own timer. */
48	export function turnOff(idle = false): void {
49	  wire.disconnect();
50	  store.dispatch({ t: "on", on: false, idle });
51	  streamDeck.logger.info(idle ? "off: idle for thirty minutes" : "off: by request");
52	}
53	
54	/** Tells whichever inspector is open where it is pointed and whether anyone is signed in. */
55	export async function sayWho(): Promise<void> {
56	  await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: loadSession() !== null, apiBase });
57	}
58	
59	function applyGlobals(g: Globals): void {
60	  apiBase = normalizeBase(g.apiBase ?? "") || DEFAULT_API;
61	  if (g.pinned !== undefined) store.dispatch({ t: "pin", id: g.pinned });
62	}
63	
64	async function readGlobals(): Promise<void> {
65	  applyGlobals(await streamDeck.settings.getGlobalSettings<Globals>());
66	}
67	
68	// A deck holding no run for half an hour closes its own socket rather than
69	// sitting on one all night. A deck following a run never times out.
70	let idleSince: number | null = null;
71	let idleTimer: ReturnType<typeof setTimeout> | null = null;
72	store.subscribe((state) => {
73	  const now = Date.now();
74	  const deadline = idleDeadline(state, idleSince ?? now);
75	  if (deadline === null) {
76	    idleSince = null;
77	    if (idleTimer) clearTimeout(idleTimer);
78	    idleTimer = null;
79	    return;
80	  }
81	  if (idleTimer) return;
82	  idleSince = now;
83	  idleTimer = setTimeout(() => {
84	    idleTimer = null;
85	    turnOff(true);
86	  }, deadline - now);
87	});
88	
89	/** The device flow's two lines, as the inspector needs them: the page and the code. */
90	function codeFromLines(): (line: string) => void {
91	  let code: string | null = null;
92	  let url: string | null = null;
93	  return (line) => {
94	    code = /^ {2}Code {2}(\S.*)$/.exec(line)?.[1]?.trim() ?? code;
95	    url = /^ {2}Open {2}(\S+)$/.exec(line)?.[1] ?? url;
96	    if (code && url) void streamDeck.ui.sendToPropertyInspector({ t: "code", code, url });
97	  };
98	}
99	
100	streamDeck.ui.onSendToPlugin<{ t?: string }>(async (ev) => {
101	  switch (ev.payload?.t) {
102	    case "signin":
103	      try {
104	        streamDeck.logger.info("sign-in: starting the device flow");
105	        await signIn({ apiBase }, codeFromLines(), () => {});
106	        store.dispatch({ t: "session", state: "ok" });
107	        streamDeck.logger.info("sign-in: done");
108	        // Signed in is not connected: the streamer presses Connect.
109	        await streamDeck.ui.sendToPropertyInspector({ t: "who", name: "you", signedIn: true, apiBase });
110	      } catch (e) {
111	        // The reason goes back to the inspector, not only to the log: the
112	        // streamer is looking at the button they pressed, and a status line
113	        // that flips back to "Not signed in" tells them nothing.
114	        const error = e instanceof Error ? e.message : "unknown";
115	        streamDeck.logger.error(`sign-in: failed (${error})`);
116	        await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: false, apiBase, error });
117	      }
118	      break;
119	    case "signout":
120	      turnOff();
121	      signOut();
122	      store.dispatch({ t: "session", state: "none" });
123	      streamDeck.logger.info("signed out");
124	      await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: false, apiBase });
125	      break;
126	    case "reconnect":
127	      turnOff();
128	      turnOn();
129	      break;
130	    default:
131	      break;
132	  }
133	});
134	
135	streamDeck.logger.setLevel("info");
136	streamDeck.settings.onDidReceiveGlobalSettings<Globals>((ev) => applyGlobals(ev.settings));
137	
138	// A flash lasts three seconds and nothing else clears it; the tick is what
139	// puts a refused key back to what it was saying.
140	setInterval(() => store.dispatch({ t: "tick" }), 1000);
141	
142	for (const a of [new Next(), new Press(), new Undo(), new Run(), new Metric(), new Connect()]) {
143	  streamDeck.actions.registerAction(a);
144	}
145	
146	void streamDeck.connect().then(async () => {
147	  // Launch is quiet: the settings, the session, and nothing else. No socket
148	  // and no token refresh until the streamer presses Connect.
149	  await readGlobals();
150	  const signedIn = loadSession() !== null;
151	  store.dispatch({ t: "session", state: signedIn ? "ok" : "none" });
152	  streamDeck.logger.info(`launched: ${signedIn ? "signed in" : "not signed in"}, not connected`);
153	});
