1	/**
2	 * Everything the plugin decides, with nothing from the SDK in it.
3	 *
4	 * A key face is a function of what the plugin knows: whether it is
5	 * signed in, whether its socket is open, which runs are held, which is
6	 * pinned, and what that run last published. `reduce` moves the state on
7	 * one event at a time; the `*Face` functions read it. Keeping them pure
8	 * is what lets the twelve states a key can be in have a test each.
9	 */
10	
11	/**
12	 * What a deck may press, right now, in the pack's own words.
13	 *
14	 * Copied from `apps/web/src/run/offer.ts`: the plugin does not import
15	 * from `apps/web`, so this shape is mirrored rather than shared.
16	 */
17	export interface Offer {
18	  seq: number;
19	  primary: { id: "roll" | "carry-on" | "close" | "enter"; label: string; kind: string } | null;
20	  moves: Array<{ id: string; label: string }>;
21	  undo: { what: string } | null;
22	  /** Why a deck cannot press this, in words a key face can carry. */
23	  needsPage: string | null;
24	  presets: Array<{ kind: string; label: string; suggestions?: string[]; items?: number }>;
25	}
26	
27	export type SessionState = "none" | "expired" | "ok";
28	export type SocketState = "closed" | "connecting" | "open";
29	export interface HeldRun {
30	  id: string;
31	  name?: string;
32	  packTitle?: string;
33	}
34	export interface Snapshot {
35	  unit?: number;
36	  words?: { unit: string };
37	  score?: { text: string };
38	  latest?: { text: string } | null;
39	  clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>;
40	  standings?: Array<{ name: string; points: number; place: number }>;
41	  counters?: Array<{ id: string; label: string; value: number }>;
42	  resources?: Array<{ id: string; label: string; value: number; max: number | null }>;
43	  at?: string;
44	  offer?: Offer;
45	}
46	export interface DeckState {
47	  session: SessionState;
48	  /** Whether the streamer has switched the deck on. No socket while false. */
49	  on: boolean;
50	  /** Whether the last time it went off, it was the idle timer rather than a press. */
51	  idleOff: boolean;
52	  socket: SocketState;
53	  runs: HeldRun[];
54	  any: boolean;
55	  pinned: string | null;
56	  attached: string | null;
57	  snapshot: Snapshot | null;
58	  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
59	}
60	export type Tone = "live" | "dim" | "refuse";
61	export interface Face {
62	  title: string;
63	  tone: Tone;
64	  when?: string;
65	  /** 0-1, set only for a running timer clock so a dial's indicator can draw it. */
66	  fraction?: number;
67	}
68	export type PressTarget = { kind: "roll" } | { kind: "move"; id: string } | { kind: "answer"; preset: string; value: string };
69	export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
70	export type DeckEvent =
71	  | { t: "session"; state: SessionState }
72	  | { t: "on"; on: boolean; idle?: boolean }
73	  | { t: "socket"; state: SocketState }
74	  | { t: "runs"; runs: HeldRun[]; any: boolean }
75	  | { t: "pin"; id: string | null }
76	  | { t: "snapshot"; snapshot: Snapshot }
77	  | { t: "drove"; ref: string; ok: boolean; say?: string; seq?: number }
78	  | { t: "tick" };
79	
80	const FLASH_MS = 3000;
81	
82	/** How long a connection that is holding nothing waits before closing itself. */
83	export const IDLE_OFF_MS = 30 * 60_000;
84	
85	export function initial(): DeckState {
86	  return {
87	    session: "none",
88	    on: false,
89	    idleOff: false,
90	    socket: "closed",
91	    runs: [],
92	    any: false,
93	    pinned: null,
94	    attached: null,
95	    snapshot: null,
96	    flash: null,
97	  };
98	}
99	
100	export function attachedRun(state: DeckState): string | null {
101	  if (state.pinned) return state.runs.some((r) => r.id === state.pinned) ? state.pinned : null;
102	  return state.runs.length === 1 ? state.runs[0]!.id : null;
103	}
104	
105	export function reduce(state: DeckState, event: DeckEvent, now: number): DeckState {
106	  switch (event.t) {
107	    case "session":
108	      return event.state === "ok" ? { ...state, session: "ok" } : { ...initial(), session: event.state, pinned: state.pinned };
109	    case "on":
110	      // Going off is a full stop: no socket, nothing held, nothing to draw
111	      // a number from. The pin is a preference, not a holding, and stays.
112	      return event.on
113	        ? { ...state, on: true, idleOff: false }
114	        : { ...state, on: false, idleOff: event.idle === true, socket: "closed", runs: [], attached: null, snapshot: null };
115	    case "socket":
116	      return event.state === "open"
117	        ? { ...state, socket: "open" }
118	        : { ...state, socket: event.state, runs: [], attached: null, snapshot: null };
119	    case "runs": {
120	      const next = { ...state, runs: event.runs, any: event.any };
121	      const attached = attachedRun(next);
122	      // A run that went away takes its numbers with it; a run that is
123	      // still here keeps them until the next snapshot lands.
124	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
125	    }
126	    case "pin": {
127	      const next = { ...state, pinned: event.id };
128	      const attached = attachedRun(next);
129	      return { ...next, attached, snapshot: attached === state.attached ? state.snapshot : null };
130	    }
131	    case "snapshot":
132	      return { ...state, snapshot: event.snapshot };
133	    case "drove": {
134	      const flash = { ref: event.ref, ok: event.ok, ...(event.say ? { say: event.say } : {}), until: now + FLASH_MS };
135	      // A `drove` verdict is the freshest seq source: the next press
136	      // should not carry a seq gone stale while it was in flight.
137	      if (event.seq === undefined || !state.snapshot?.offer) return { ...state, flash };
138	      return { ...state, flash, snapshot: { ...state.snapshot, offer: { ...state.snapshot.offer, seq: event.seq } } };
139	    }
140	    case "tick":
141	      return state.flash && state.flash.until <= now ? { ...state, flash: null } : state;
142	  }
143	}
144	
145	/** What a key says about the run once the deck is signed in and switched on. */
146	function held(state: DeckState): Face | null {
147	  if (state.socket !== "open") return { title: "Offline", tone: "dim" };
148	  if (state.pinned && !state.runs.some((r) => r.id === state.pinned)) return { title: "That run has ended", tone: "dim" };
149	  if (state.runs.length === 0) return state.any ? { title: "No run open", tone: "dim" } : { title: "Not synced", tone: "dim" };
150	  if (!state.attached) return { title: "Pick a run", tone: "dim" };
151	  return null;
152	}
153	
154	/** The state every key shares before any of them has something of its own to say. */
155	function common(state: DeckState): Face | null {
156	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
157	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
158	  // A key that depends on the connection says to make it first: the state
159	  // on top, the thing to do about it beneath.
160	  if (!state.on) return { title: "Not connected", tone: "dim", when: "press Connect" };
161	  return held(state);
162	}
163	
164	/** The run a deck is following, named, or nothing. */
165	function attachedName(state: DeckState): Face | null {
166	  const run = state.runs.find((r) => r.id === state.attached);
167	  if (!run) return null;
168	  return { title: run.name ?? run.packTitle ?? run.id, tone: "live", ...(run.packTitle && run.name ? { when: run.packTitle } : {}) };
169	}
170	
171	/**
172	 * The Connect key, which reports the connection rather than the run behind it.
173	 *
174	 * It is the one key that has something to say while the deck is off, so it
175	 * skips the "Not connected" every other key stops at and names the state it
176	 * is actually in - down by choice, down by the idle timer, or on its way up.
177	 */
178	export function connectFace(state: DeckState): Face {
179	  if (state.session === "none") return { title: "Sign in", tone: "dim" };
180	  if (state.session === "expired") return { title: "Sign in again", tone: "dim" };
181	  if (!state.on) return state.idleOff ? { title: "Idle · press to connect", tone: "dim" } : { title: "Offline", tone: "dim" };
182	  if (state.socket === "connecting") return { title: "Connecting", tone: "dim" };
183	  return held(state) ?? attachedName(state) ?? { title: "Connected", tone: "live" };
184	}
185	
186	/**
187	 * When a connection that is holding nothing should close itself.
188	 *
189	 * `since` is when it last had nothing to follow. Null means the clock is not
190	 * running at all - a deck following a live run never times out, however long
191	 * the stream goes, and a deck that is off or still dialing has nothing to
192	 * give up on.
193	 */
194	export function idleDeadline(state: DeckState, since: number): number | null {
195	  if (!state.on || state.socket !== "open" || state.runs.length > 0) return null;
196	  return since + IDLE_OFF_MS;
197	}
198	
199	function flashed(state: DeckState): Face | null {
200	  if (!state.flash || state.flash.ok) return null;
201	  return { title: state.flash.say ?? "No", tone: "refuse" };
202	}
203	
204	export function nextFace(state: DeckState): Face {
205	  const c = common(state) ?? flashed(state);
206	  if (c) return c;
207	  const offer = state.snapshot?.offer;
208	  if (!offer) return { title: "Loading…", tone: "dim" };
209	  if (offer.primary) return { title: offer.primary.label, tone: "live" };
210	  return { title: offer.needsPage ?? "Nothing to press", tone: offer.needsPage ? "refuse" : "dim" };
211	}
212	
213	export function pressFace(state: DeckState, target: PressTarget): Face {
214	  const c = common(state) ?? flashed(state);
215	  if (c) return c;
216	  const offer = state.snapshot?.offer;
217	  if (!offer) return { title: "Loading…", tone: "dim" };
218	  if (target.kind === "roll")
219	    return offer.primary?.id === "roll" ? { title: offer.primary.label, tone: "live" } : { title: "Nothing to roll", tone: "dim" };
220	  if (target.kind === "move") {
221	    const m = offer.moves.find((x) => x.id === target.id);
222	    return m ? { title: m.label, tone: "live" } : { title: "Not on offer", tone: "dim" };
223	  }
224	  const p = offer.presets.find((x) => x.kind === target.preset);
225	  return p ? { title: target.value, tone: "live", when: p.label } : { title: target.value, tone: "dim", when: "Not now" };
226	}
227	
228	export function undoFace(state: DeckState): Face {
229	  const c = common(state) ?? flashed(state);
230	  if (c) return c;
231	  const undo = state.snapshot?.offer?.undo;
232	  return undo ? { title: "Undo", tone: "live", when: undo.what } : { title: "Nothing to undo", tone: "dim" };
233	}
234	
235	export function runFace(state: DeckState): Face {
236	  return common(state) ?? attachedName(state) ?? { title: "Pick a run", tone: "dim" };
237	}
238	
239	/** How far a clock has moved since the snapshot that reported it, in ms. */
240	function clockElapsedMs(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): number {
241	  const since = c.status === "running" ? now - Date.parse(at) : 0;
242	  return c.elapsedMs + since;
243	}
244	
245	/** The arithmetic `stream-api.md` publishes, so a key agrees with a widget to the second. */
246	function clockText(c: NonNullable<Snapshot["clocks"]>[number], at: string, now: number): string {
247	  const elapsed = clockElapsedMs(c, at, now);
248	  const ms = c.seconds === null ? elapsed : Math.max(0, c.seconds * 1000 - elapsed);
249	  const s = Math.floor(ms / 1000);
250	  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
251	}
252	
253	export function metricFace(state: DeckState, field: MetricField, now: number): Face {
254	  const c = common(state);
255	  if (c) return c;
256	  const snap = state.snapshot;
257	  if (!snap) return { title: "Loading…", tone: "dim" };
258	  if (field === "score") return { title: snap.score?.text ?? "—", tone: "live", when: "Score" };
259	  if (field === "unit") return { title: String(snap.unit ?? "—"), tone: "live", when: snap.words?.unit ?? "Unit" };
260	  if (field === "latest") return { title: snap.latest?.text ?? "—", tone: "live" };
261	  if (field === "leader") {
262	    const top = snap.standings?.[0];
